// IW8 Radiant Suite - Replay vision fields (roadmap 5.6): the field table from the converter and the
// "name=value;name=value" override text that the map's iw8r_vision key holds (see atmosphere.h).
// The table itself is generated by tools/gen_vision_fields.py into vision_fields.inc. Do not edit that file.
#pragma once

#include <string>
#include <utility>
#include <vector>

namespace iw8r {

struct VisionField {
    const char* name;         // dev name, or the token for an unnamed field (the converter accepts both)
    const char* type;         // converter kind: scalar (1 number), vector (3 numbers), others are not number-settable
    const char* defaultText;  // stock default from the template, "" when the template does not set it
    const char* group;        // fog, sky, sun, tonemap, exposure, bloom, grade, film, dof or misc
};

// All fields in converter order (index = vision field index).
const std::vector<VisionField>& visionFields();

// Case-insensitive lookup by name. nullptr when unknown. The pointer stays valid for the program's life.
const VisionField* findVisionField(const std::string& name);

// Splits "name=value;name=value" into ordered pairs. Blanks around names and values are trimmed and empty items are
// skipped. Returns false and sets *err on a pair without '=', an empty name or an empty value. `out` is cleared first.
bool parseVisionOverrides(const std::string& text, std::vector<std::pair<std::string, std::string>>& out, std::string* err);

// Inverse of parseVisionOverrides: "name=value;name=value" with no spaces around the separators.
std::string formatVisionOverrides(const std::vector<std::pair<std::string, std::string>>& pairs);

// "" when the value text fits the field's type (number count and number syntax), else a short reason.
// Types: scalar takes one number, vector three (x y z), bool 0 or 1. Other converter kinds take no number.
std::string checkVisionValue(const VisionField& f, const std::string& value);

}  // namespace iw8r
